-- [phiên A] mặc định = READ COMMITTED
BEGIN;
SELECT total FROM orders WHERE id = 1;
-- [phiên B] UPDATE +1000; COMMIT;
SELECT total FROM orders WHERE id = 1;
COMMIT;   -- 2 lần đọc KHÁC nhau

-- [phiên A] chỉ đổi đúng câu BEGIN:
BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT total FROM orders WHERE id = 1;
-- [phiên B] UPDATE +1000; COMMIT;
SELECT total FROM orders WHERE id = 1;
COMMIT;   -- 2 lần đọc GIỐNG nhau
-- snapshot chốt từ câu lệnh ĐẦU TIÊN
